// Service-worker registration + the "update available" prompt.
//
// The service worker (generated by vite-plugin-pwa, production builds only) caches the app shell
// so the app opens with no network. When a new version has been downloaded it WAITS: this
// component shows a bar and the new version is activated only when the user taps Reload. The
// page is never reloaded automatically — a bill in progress is never lost to an update.
import { useEffect, useRef, useState } from "react";
import { registerSW } from "virtual:pwa-register";

export function UpdatePrompt() {
  const [needRefresh, setNeedRefresh] = useState(false);
  const [offlineReady, setOfflineReady] = useState(false);
  const update = useRef(null);

  useEffect(() => {
    if (!import.meta.env.PROD || !("serviceWorker" in navigator)) return;
    update.current = registerSW({
      immediate: true,
      onNeedRefresh: () => setNeedRefresh(true),
      onOfflineReady: () => {
        setOfflineReady(true);
        setTimeout(() => setOfflineReady(false), 4000);
      },
      onRegisterError: (e) => console.error("service worker registration failed", e),
    });
  }, []);

  if (!needRefresh && !offlineReady) return null;
  return (
    <div
      role="status"
      style={{
        position: "fixed",
        left: 12,
        right: 12,
        bottom: 12,
        zIndex: 1000,
        maxWidth: 460,
        margin: "0 auto",
        background: "#10331F",
        color: "#fff",
        borderRadius: 12,
        padding: "12px 14px",
        display: "flex",
        alignItems: "center",
        gap: 10,
        boxShadow: "0 8px 28px rgba(0,0,0,.35)",
        fontSize: 13.5,
        fontFamily: "system-ui, sans-serif",
      }}
    >
      {needRefresh ? (
        <>
          <span style={{ flex: 1 }}>🔄 Update available — reload when you are between bills.</span>
          <button
            onClick={() => update.current && update.current(true)}
            style={{
              minHeight: 44,
              padding: "0 16px",
              borderRadius: 9,
              border: "none",
              background: "#3FB873",
              color: "#0B2416",
              fontWeight: 800,
              cursor: "pointer",
            }}
          >
            Reload
          </button>
          <button
            onClick={() => setNeedRefresh(false)}
            aria-label="Dismiss update notice"
            style={{
              minHeight: 44,
              padding: "0 12px",
              borderRadius: 9,
              border: "1px solid #2A5A3E",
              background: "none",
              color: "#C8E2D4",
              cursor: "pointer",
            }}
          >
            Later
          </button>
        </>
      ) : (
        <span style={{ flex: 1 }}>✓ Ready to work offline on this device.</span>
      )}
    </div>
  );
}
